AA;ECOF;EDNE;;;IAGE,eAAA;ECQJ;EDPI;;;IACA,yBAAA;ECWJ;EDNA;IACE,aAAA;ECQF;EDLA;IACE,aAAA;IACA,WAAA;ECOF;EDJA;IACE,sBAAA;IACA,oBAAA;ECMF;EDJA;IACE,eAAA;ECMF;EDHA;IACE,kBAAA;ECKF;AACF;ADDA;EACE,YAAA;ACGF","file":"place_an_ad.css","sourcesContent":["@import \"./variables\";\n@import \"./mixins\";\n\n.create_advertisement {\n  margin-top: 15px;\n\n  & form {\n    margin-bottom: 10px;\n  }\n}\n\n:where(\n    .additional_information,\n    .category_select,\n    form,\n    .contact,\n    .bearer_company_additional_info,\n    .region_select,\n    .information_select,\n    .inner_select\n  ) {\n  display: flex;\n  flex-direction: column;\n  gap: 10px;\n}\n\n.label_fields {\n  flex: 0 0 250px;\n  @include fonts($defaultColor, 14px, 400);\n}\n\n:where(.region_select, .category_select, .information_select, .store_select) {\n  flex: 0 1 320px;\n}\n\n.item_input {\n  display: flex;\n  align-items: center;\n  gap: 10px;\n\n  & input,\n  select,\n  textarea {\n    width: 100%;\n    max-width: 320px;\n    border: 1px solid #d4d4d4;\n    padding: 5px;\n    border-radius: 8px;\n    @include fonts($defaultColor, 14px, 400);\n    &:focus {\n      border: 1px solid #3779eb;\n    }\n  }\n\n  & input[type=\"radio\"] {\n    width: initial;\n  }\n}\n\n.photo {\n  display: flex;\n  align-items: center;\n  gap: 10px;\n}\n\n.photo_file {\n  max-width: 320px;\n  width: 100%;\n    border-radius: 8px;\n  font-family: \"Trebuchet MS\", sans-serif;\n    font-weight: 400;\n    font-style: normal;\n    color: #000;\n    font-size: 14px;\n  border: 1px solid #d4d4d4;\n}\n\n.photo_preview {\n  display: grid;\n  grid-template-columns: repeat(auto-fill, minmax(150px, 1fr));\n  gap: 5px;\n  margin: 5px;\n}\n\n.photo_preview {\n  display: none;\n\n  &:has(.photo_img) {\n    display: grid;\n  }\n}\n\n.bearer_company_additional_info {\n  display: none;\n\n  &:has(div) {\n    display: flex;\n  }\n}\n\n.add_adv {\n  max-width: 320px;\n}\n\n.description_radio {\n  display: flex;\n  align-items: center;\n  gap: 10px;\n  & label {\n    @include fonts($defaultColor, 14px, 400);\n  }\n}\n\n.photo_img {\n  position: relative;\n  border: 1px solid $asideLinksColor;\n  border-radius: 3px;\n  & img {\n    max-height: 85px;\n    width: 100%;\n    height: 100%;\n    object-fit: cover;\n    object-position: center;\n    border-radius: 3px;\n  }\n\n  &:hover {\n    .delete_img {\n      transition: 0.1s ease;\n      opacity: 1;\n      display: block;\n    }\n  }\n}\n\n.delete_img {\n  border-radius: 0 3px 0 0;\n  transition: 0.3s ease;\n  opacity: 0;\n  position: absolute;\n  top: 0;\n  right: 0;\n  width: 15px;\n  height: 15px;\n  background: rgb(0, 0, 0, 0.5);\n  cursor: pointer;\n  z-index: 2;\n\n  &::after,\n  &::before {\n    content: \"\";\n    display: block;\n    width: 100%;\n    height: 2px;\n    background: #fff;\n    position: absolute;\n    top: 45%;\n    right: 0;\n    z-index: 1;\n    transform: rotate(45deg);\n  }\n  &::before {\n    transform: rotate(-45deg);\n  }\n  &:hover {\n        & ~.img_preview {\n            opacity: 0.5;\n        }\n    &::after,\n    &::before {\n      background: #FFA07A;\n      transition: 0.3s ease-out;\n    }\n    }\n}\n\n.main_img {\n    padding: 2px;\n    outline: 2px solid #3CB371;\n}\n\n.img_preview {\n    width: 100%;\n    height: 100%;\n    position: relative;\n    transition: 0.3s ease;\n    cursor: pointer;\n    opacity: 1;\n    &:hover {\n        padding: 2px;\n        outline: 2px solid #3CB371;\n        transition: 0.1s ease-out;\n    }\n\n    &:active {\n        top: 2px;\n        transition: 0.3s ease;\n    }\n}\n\n.advertisement_notification-success {\n  display: flex;\n  margin: 200px auto;\n  flex-direction: column;\n  gap: 15px;\n  align-items: center;\n  justify-content: center;\n  @include fonts($defaultColor, 20px, 400);\n}\n\n.continue__link {\n  text-align: center;\n  @include fonts($defaultColor, 14px, 400);\n  max-width: 200px;\n  background: #F5F5F5;\n\n}\n\n.error {\n  @include fonts($colorHover, 14px, 400);\n}\n\n.input_error {\n  border: 1px solid red !important;\n}\n\n@media (max-width: 992px) {\n  .item_input {\n    align-items: initial;\n    flex-direction: column;\n    & input,\n    select,\n    textarea {\n      max-width: none;\n      &:focus {\n      border: 1px solid #3779eb;\n    }\n    }\n  }\n\n  .label_fields {\n    flex: initial;\n  }\n\n  :where(.region_select, .category_select, .information_select, .store_select) {\n    flex: initial;\n    width: 100%;\n  }\n\n  .photo {\n    flex-direction: column;\n    align-items: initial;\n  }\n  .add_adv {\n    max-width: none;\n  }\n\n  .advertisement_notification-success {\n    margin: 100px auto;\n  }\n\n}\n\n.file_input {\n  padding: 5px;\n}\n\n",".create_advertisement {\n  margin-top: 15px;\n}\n.create_advertisement form {\n  margin-bottom: 10px;\n}\n\n:where(.additional_information,\n.category_select,\nform,\n.contact,\n.bearer_company_additional_info,\n.region_select,\n.information_select,\n.inner_select) {\n  display: flex;\n  flex-direction: column;\n  gap: 10px;\n}\n\n.label_fields {\n  flex: 0 0 250px;\n  font-family: \"Trebuchet MS\", sans-serif;\n  font-weight: 400;\n  font-style: normal;\n  color: black;\n  font-size: 14px;\n}\n\n:where(.region_select, .category_select, .information_select, .store_select) {\n  flex: 0 1 320px;\n}\n\n.item_input {\n  display: flex;\n  align-items: center;\n  gap: 10px;\n}\n.item_input input,\n.item_input select,\n.item_input textarea {\n  width: 100%;\n  max-width: 320px;\n  border: 1px solid #d4d4d4;\n  padding: 5px;\n  border-radius: 8px;\n  font-family: \"Trebuchet MS\", sans-serif;\n  font-weight: 400;\n  font-style: normal;\n  color: black;\n  font-size: 14px;\n}\n.item_input input:focus,\n.item_input select:focus,\n.item_input textarea:focus {\n  border: 1px solid #3779eb;\n}\n.item_input input[type=radio] {\n  width: initial;\n}\n\n.photo {\n  display: flex;\n  align-items: center;\n  gap: 10px;\n}\n\n.photo_file {\n  max-width: 320px;\n  width: 100%;\n  border-radiu